-- Sequence and defined type
CREATE SEQUENCE IF NOT EXISTS students_id_seq;

-- Table Definition
CREATE TABLE "public"."students" (
    "id" int8 NOT NULL DEFAULT nextval('students_id_seq'::regclass),
    "nisn" varchar(255) NOT NULL,
    "name" varchar(255) NOT NULL,
    "classroom_id" int8 NOT NULL,
    "created_at" timestamp(0),
    "updated_at" timestamp(0),
    "deleted_at" timestamp(0),
    "status" varchar(255) NOT NULL DEFAULT 'Aktif'::character varying,
    "status_keterangan" varchar(255),
    PRIMARY KEY ("id")
);


-- Indices
CREATE UNIQUE INDEX students_nisn_unique ON public.students USING btree (nisn);
CREATE INDEX students_classroom_id_index ON public.students USING btree (classroom_id);

ALTER TABLE "public"."students" ADD FOREIGN KEY ("classroom_id") REFERENCES "public"."classrooms"("id");

